import sys
import math

def reduce(arr):
    for i in range(len(arr) - 1, -1, -1):
        if arr[i] != 0:
            if i == len(arr) - 1:
                return arr
            return arr[:i + 1]
    return []

def multiply_naive(a, b):
    c = [0] * (len(a) + len(b) - 1)
    limit = 8 * 998244353 * 998244353
    for i in range(len(a)):
        for j in range(len(b)):
            c[i + j] += a[i] * b[j]
            if c[i + j] >= limit:
                c[i + j] -= limit
    for i in range(len(c)):
        c[i] %= 998244353
    return c

def ntt_transform(src, n, inv, P, g):
    res = src[:]
    h = n.bit_length() - 1
    K = 1 << (h + 1)
    H = (K.bit_length() - 1) * 2
    M = (K * K) // P
    wws = [0] * (1 << (h - 1))
    w = (1 << 32) % P
    dw = pow(g, P - 1 - (P - 1) // n, P) if inv else pow(g, (P - 1) // n, P)
    for k in range(1 << (h - 1)):
        wws[k] = w
        w = (w * dw) % P
    invN = invl(n, P)
    for i in range(h):
        for j in range(1 << i):
            s = j << (h - i)
            t = s | (1 << (h - i - 1))
            for k in range(1 << (h - i - 1)):
                u = (res[s + k] - res[t + k] + 2 * P) * wws[k] % P
                res[s + k] = res[s + k] + res[t + k]
                if res[s + k] >= 2 * P:
                    res[s + k] -= 2 * P
                Q = ((u << 32) * invN) >> 32
                res[t + k] = (u >> 32) - (Q * P >> 32) + P
        if i < h - 1:
            for k in range(1 << (h - i - 2)):
                wws[k] = wws[k * 2]
    for i in range(n):
        if res[i] >= P:
            res[i] -= P
    for i in range(n):
        rev = int('{:032b}'.format(i)[::-1], 2) >> (32 - h)
        if i < rev:
            res[i], res[rev] = res[rev], res[i]
    if inv:
        for i in range(n):
            res[i] = (res[i] * invN) % P
    return res

def pow_mod(a, n, m):
    r = 1
    x = n
    while x > 0:
        if x & 1:
            r = (r * a) % m
        a = (a * a) % m
        x >>= 1
    return r

def invl(a, m):
    b = m
    p = 1
    q = 0
    while b > 0:
        c = a // b
        d = a
        a = b
        b = d % b
        d = p
        p = q
        q = d - c * q
    return p % m

def convolute_simple(a, b, P, g):
    m = 1 << (max(a.__len__(), b.__len__()).bit_length() + 1)
    fa = ntt_transform(a, m, False, P, g)
    if a is b:
        fb = fa
    else:
        fb = ntt_transform(b, m, False, P, g)
    for i in range(m):
        fa[i] = fa[i] * fb[i] % P
    return ntt_transform(fa, m, True, P, g)

def main():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    K = int(input_data[1])
    d = list(map(int, input_data[2:2+K]))
    f = [0] * 20
    for i in range(K):
        for j in range(K):
            f[10 + d[i] - d[j]] += 1
    n //= 2
    g = [1]
    for D in range(17, -1, -1):
        g = reduce(convolute_simple(g, g, 998244353, 3))
        if (n << (~D)) < 0:
            g = reduce(multiply_naive(g, f))
    print(g[n * 10] if n * 10 < len(g) else 0)

if __name__ == "__main__":
    main()

